const { chromium } = require('/Users/yuvalt/personal/visual-renderer/bench/versus-browser/tooling/node_modules/playwright');
(async () => {
  const b = await chromium.launch();
  let bad = 0;
  for (const [n,w,h,s] of [['portrait',1080,1350,1],['wide',1200,1000,0.85],['sky',300,600,0.28]]) {
    const p = await b.newPage({ viewport:{width:w,height:h} });
    await p.goto('file://' + process.cwd() + '/' + n + '.html');
    await p.waitForTimeout(500);
    const r = await p.evaluate(() => {
      const st = document.querySelector('.stage');
      const sr = st.getBoundingClientRect();
      // every leaf element, in *device* px, checked against the viewport
      const leaves = [...st.querySelectorAll('*')].filter(e => !e.children.length || e.tagName==='H1');
      let minT=1e9,maxB=-1e9,minL=1e9,maxR=-1e9;
      for (const e of leaves) {
        const b = e.getBoundingClientRect();
        if (b.width===0||b.height===0) continue;
        minT=Math.min(minT,b.top); maxB=Math.max(maxB,b.bottom);
        minL=Math.min(minL,b.left); maxR=Math.max(maxR,b.right);
      }
      const bands=[...document.querySelectorAll('.photoband,.cta')].map(e=>{const b=e.getBoundingClientRect();return [+b.left.toFixed(1),+b.right.toFixed(1)];});
      const cols=[...document.querySelectorAll('.cand')].map(e=>{const b=e.getBoundingClientRect();return +((b.left+b.right)/2).toFixed(1);});
      const img=document.querySelector('.photoband img');
      return { stageH: st.clientHeight, contentLogical: null, minT:+minT.toFixed(1), maxB:+maxB.toFixed(1),
        minL:+minL.toFixed(1), maxR:+maxR.toFixed(1), bands, cols,
        natural: img.naturalWidth+'x'+img.naturalHeight,
        scroll: document.documentElement.scrollWidth+'x'+document.documentElement.scrollHeight };
    });
    const gaps = r.cols.slice(1).map((c,i)=>+(c-r.cols[i]).toFixed(1));
    const fullW = r.bands.every(([l,rr]) => l<=0.5 && rr>=w-0.5);
    const inside = r.minT>=-0.5 && r.maxB<=h+0.5 && r.minL>=-0.5 && r.maxR<=w+0.5;
    if (!fullW || !inside || r.scroll!==`${w}x${h}`) bad++;
    console.log(`${n.padEnd(9)} content box T${r.minT} B${r.maxB} L${r.minL} R${r.maxR} (vp ${w}x${h})`,
      `| margins top ${r.minT.toFixed(1)} bot ${(h-r.maxB).toFixed(1)} side ${r.minL.toFixed(1)}/${(w-r.maxR).toFixed(1)}`);
    console.log(`          bands full-width: ${fullW} ${JSON.stringify(r.bands)} | col centers ${JSON.stringify(r.cols)} gaps ${JSON.stringify(gaps)}`);
    console.log(`          all content inside viewport: ${inside} | scroll ${r.scroll} | img natural ${r.natural}`);
    await p.close();
  }
  await b.close();
  console.log(bad ? `\nFAIL (${bad})` : '\nALL CHECKS PASS');
})();
